package localscan

import (
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

// lfsLikeHook mimics a hook generated by another tool that reads stdin.
const lfsLikeHook = "#!/bin/sh\n" +
	"command -v example-tool >/dev/null 2>&1 || { echo >&2 \"example-tool is missing\"; exit 2; }\n" +
	"example-tool pre-push \"$@\"\n"

func writeTestHook(t *testing.T, dir, name, content string, mode os.FileMode) string {
	t.Helper()
	path := filepath.Join(dir, name)
	if err := os.WriteFile(path, []byte(content), mode); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(path, mode); err != nil {
		t.Fatal(err)
	}
	return path
}

func readTestHook(t *testing.T, path string) string {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return string(data)
}

func TestInstallHookMergeInsertsBlockAfterShebang(t *testing.T) {
	for _, name := range HookNames {
		t.Run(name, func(t *testing.T) {
			dir := t.TempDir()
			path := writeTestHook(t, dir, name, lfsLikeHook, 0o640)

			if _, err := InstallHook(dir, name, InstallHookOptions{Merge: true, LogLevel: "debug"}); err != nil {
				t.Fatalf("InstallHook(Merge) error = %v", err)
			}
			got := readTestHook(t, path)
			if !strings.HasPrefix(got, "#!/bin/sh\n"+mergeBeginMarker+"\n") {
				t.Errorf("block is not placed right after the shebang:\n%s", got)
			}
			if !strings.HasSuffix(got, mergeEndMarker+"\n"+strings.TrimPrefix(lfsLikeHook, "#!/bin/sh\n")) {
				t.Errorf("original content is not kept after the block:\n%s", got)
			}
			if !strings.Contains(got, "--log-level debug") {
				t.Errorf("block does not carry the scan flags:\n%s", got)
			}
			if hasMarkerLine(got) {
				t.Error("merged hook must not carry the standalone marker line")
			}
			if runtime.GOOS != "windows" {
				info, err := os.Stat(path)
				if err != nil {
					t.Fatal(err)
				}
				if info.Mode().Perm() != 0o740 {
					t.Errorf("mode = %v, want %v", info.Mode().Perm(), os.FileMode(0o740))
				}
			}

			statuses, err := HookStatuses(dir, []string{name})
			if err != nil {
				t.Fatal(err)
			}
			if statuses[0].State != HookStateMerged {
				t.Errorf("State = %q, want %q", statuses[0].State, HookStateMerged)
			}
		})
	}
}

func TestInstallHookMergedIsUpdatedInPlace(t *testing.T) {
	dir := t.TempDir()
	path := writeTestHook(t, dir, "pre-push", lfsLikeHook, 0o755)
	if _, err := InstallHook(dir, "pre-push", InstallHookOptions{Merge: true}); err != nil {
		t.Fatal(err)
	}
	for _, opts := range []InstallHookOptions{
		{Merge: true, LogLevel: "warn"},
		{LogLevel: "error"},
		{Force: true, LogLevel: "info"},
	} {
		if _, err := InstallHook(dir, "pre-push", opts); err != nil {
			t.Fatalf("InstallHook(%+v) error = %v", opts, err)
		}
		got := readTestHook(t, path)
		if c := strings.Count(got, mergeBeginMarker); c != 1 {
			t.Fatalf("begin marker count = %d, want 1:\n%s", c, got)
		}
		if !strings.Contains(got, "--log-level "+opts.LogLevel) {
			t.Errorf("block was not updated to log level %q:\n%s", opts.LogLevel, got)
		}
		if !strings.HasSuffix(got, strings.TrimPrefix(lfsLikeHook, "#!/bin/sh\n")) {
			t.Errorf("original content was not kept:\n%s", got)
		}
	}
}

func TestUninstallHookMergedRestoresOriginal(t *testing.T) {
	originals := map[string]string{
		"lf":         lfsLikeHook,
		"crlf":       "#!/bin/sh\r\nexample-tool pre-push \"$@\"\r\n",
		"no-newline": "#!/bin/sh\nexample-tool pre-push \"$@\"",
		"env":        "#!/usr/bin/env bash\nexample-tool pre-push \"$@\"\n",
		"errexit":    "#!/bin/sh -e\nexample-tool pre-push \"$@\"\n",
		"two-lines":  "#!/bin/sh\n\n",
	}
	for label, original := range originals {
		t.Run(label, func(t *testing.T) {
			dir := t.TempDir()
			path := writeTestHook(t, dir, "pre-push", original, 0o755)
			if _, err := InstallHook(dir, "pre-push", InstallHookOptions{Merge: true}); err != nil {
				t.Fatalf("InstallHook(Merge) error = %v", err)
			}
			removed, err := UninstallHook(dir, "pre-push", false)
			if err != nil {
				t.Fatalf("UninstallHook() error = %v", err)
			}
			if !removed {
				t.Error("UninstallHook() removed = false, want true")
			}
			if got := readTestHook(t, path); got != original {
				t.Errorf("content after uninstall = %q, want %q", got, original)
			}
		})
	}
}

func TestInstallHookMergeRejects(t *testing.T) {
	cases := map[string]string{
		"python":        "#!/usr/bin/env python3\nprint('hook')\n",
		"no-shebang":    "echo hook\n",
		"shebang-only":  "#!/bin/sh",
		"orphan-begin":  "#!/bin/sh\n" + mergeBeginMarker + "\necho hook\n",
		"orphan-end":    "#!/bin/sh\n" + mergeEndMarker + "\necho hook\n",
		"reversed":      "#!/bin/sh\n" + mergeEndMarker + "\n" + mergeBeginMarker + "\n",
		"duplicated":    "#!/bin/sh\n" + mergeBeginMarker + "\n" + mergeEndMarker + "\n" + mergeBeginMarker + "\n" + mergeEndMarker + "\n",
		"double-begins": "#!/bin/sh\n" + mergeBeginMarker + "\n" + mergeBeginMarker + "\n" + mergeEndMarker + "\n",
	}
	for label, original := range cases {
		t.Run(label, func(t *testing.T) {
			dir := t.TempDir()
			path := writeTestHook(t, dir, "pre-push", original, 0o755)
			if _, err := InstallHook(dir, "pre-push", InstallHookOptions{Merge: true}); err == nil {
				t.Error("InstallHook(Merge) succeeded, want error")
			}
			if _, err := UninstallHook(dir, "pre-push", false); err == nil {
				t.Error("UninstallHook() succeeded, want error")
			}
			if got := readTestHook(t, path); got != original {
				t.Errorf("hook was modified: %q", got)
			}
			statuses, err := HookStatuses(dir, []string{"pre-push"})
			if err != nil {
				t.Fatal(err)
			}
			if statuses[0].State != HookStateUnmanaged {
				t.Errorf("State = %q, want %q", statuses[0].State, HookStateUnmanaged)
			}
		})
	}
}

func TestInstallHookMergeRejectsSymlink(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("symlinks require privileges on Windows")
	}
	dir := t.TempDir()
	target := filepath.Join(t.TempDir(), "target")
	if err := os.WriteFile(target, []byte(lfsLikeHook), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.Symlink(target, filepath.Join(dir, "pre-push")); err != nil {
		t.Fatal(err)
	}
	if _, err := InstallHook(dir, "pre-push", InstallHookOptions{Merge: true}); err == nil {
		t.Error("InstallHook(Merge) succeeded on a symlink, want error")
	}
	if got := readTestHook(t, target); got != lfsLikeHook {
		t.Errorf("symlink target was modified: %q", got)
	}
}

func TestInstallHookMergeWithoutExistingHook(t *testing.T) {
	dir := t.TempDir()
	path, err := InstallHook(dir, "pre-push", InstallHookOptions{Merge: true})
	if err != nil {
		t.Fatal(err)
	}
	if !hasMarkerLine(readTestHook(t, path)) {
		t.Error("expected a standalone hook when no hook exists")
	}
}

func TestIsMergeableShebang(t *testing.T) {
	cases := map[string]bool{
		"#!/bin/sh":                      true,
		"#!/bin/sh -e":                   true,
		"#! /bin/bash":                   true,
		"#!/usr/bin/env sh":              true,
		"#!/usr/bin/env -S bash -e":      true,
		"#!/usr/bin/env -S -u sh awk -f": false,
		"#!/usr/bin/env -i sh":           false,
		"#!/bin/zsh\r":                   true,
		"#!/usr/bin/env python3":         false,
		"#!/usr/bin/env":                 false,
		"#!":                             false,
		"echo hi":                        false,
	}
	for line, want := range cases {
		if got := isMergeableShebang(line); got != want {
			t.Errorf("isMergeableShebang(%q) = %v, want %v", line, got, want)
		}
	}
}

// runMergedPrePush installs a merged pre-push hook in front of a script that
// records its stdin and first argument, runs it with a fake gh on PATH, and
// returns the recorded gh invocations, the stdin and argument the original
// hook body received, and the hook exit error.
func runMergedPrePush(t *testing.T, shebang, stdin, failOn string) ([]string, string, string, error) {
	t.Helper()
	if runtime.GOOS == "windows" {
		t.Skip("executing hook scripts requires a POSIX shell")
	}
	if _, err := exec.LookPath("sh"); err != nil {
		t.Skip("sh is not available")
	}
	work := t.TempDir()
	bin := filepath.Join(work, "bin")
	if err := os.Mkdir(bin, 0o755); err != nil {
		t.Fatal(err)
	}
	writeTestHook(t, bin, "gh", `#!/bin/sh
printf '%s\n' "$*" >> "$FAKE_GH_LOG"
if [ -n "$FAKE_GH_FAIL" ]; then
	case "$*" in *"$FAKE_GH_FAIL"*) exit 1 ;; esac
fi
exit 0
`, 0o755)

	hooks := filepath.Join(work, "hooks")
	if err := os.Mkdir(hooks, 0o755); err != nil {
		t.Fatal(err)
	}
	original := shebang + `
cat > "$OUT_STDIN"
printf '%s' "$1" > "$OUT_ARG"
`
	path := writeTestHook(t, hooks, "pre-push", original, 0o755)
	if _, err := InstallHook(hooks, "pre-push", InstallHookOptions{Merge: true}); err != nil {
		t.Fatalf("InstallHook(Merge) error = %v", err)
	}

	logPath := filepath.Join(work, "gh.log")
	outStdin := filepath.Join(work, "stdin.out")
	outArg := filepath.Join(work, "arg.out")
	cmd := exec.Command(path, "origin", "https://example.invalid/repo.git")
	cmd.Stdin = strings.NewReader(stdin)
	cmd.Env = append(os.Environ(),
		"PATH="+bin+string(os.PathListSeparator)+os.Getenv("PATH"),
		"FAKE_GH_LOG="+logPath,
		"FAKE_GH_FAIL="+failOn,
		"OUT_STDIN="+outStdin,
		"OUT_ARG="+outArg,
	)
	out, runErr := cmd.CombinedOutput()
	if runErr != nil {
		t.Logf("hook output:\n%s", out)
	}

	var calls []string
	if data, err := os.ReadFile(logPath); err == nil {
		calls = strings.Split(strings.TrimSuffix(string(data), "\n"), "\n")
	}
	readOptional := func(p string) string {
		data, err := os.ReadFile(p)
		if err != nil {
			return "<not run>"
		}
		return string(data)
	}
	return calls, readOptional(outStdin), readOptional(outArg), runErr
}

const (
	testZeroSHA   = "0000000000000000000000000000000000000000"
	testLocalSHA1 = "1111111111111111111111111111111111111111"
	testLocalSHA2 = "2222222222222222222222222222222222222222"
	testRemoteSHA = "3333333333333333333333333333333333333333"
)

func TestMergedPrePushForwardsRefsToOriginalHook(t *testing.T) {
	for _, shebang := range []string{"#!/bin/sh", "#!/bin/sh -e"} {
		t.Run(shebang, func(t *testing.T) {
			stdin := "refs/heads/feature " + testLocalSHA1 + " refs/heads/feature " + testRemoteSHA + "\n" +
				"refs/heads/topic " + testLocalSHA2 + " refs/heads/topic " + testZeroSHA + "\n"
			calls, gotStdin, gotArg, err := runMergedPrePush(t, shebang, stdin, "")
			if err != nil {
				t.Fatalf("hook failed: %v", err)
			}
			if len(calls) != 2 {
				t.Fatalf("gh calls = %q, want 2", calls)
			}
			if !strings.Contains(calls[0], "--rev-range "+testRemoteSHA+".."+testLocalSHA1) {
				t.Errorf("first scan = %q, want a rev range", calls[0])
			}
			if !strings.Contains(calls[1], "--unpushed --rev "+testLocalSHA2+" --remote origin") {
				t.Errorf("second scan = %q, want an unpushed scan", calls[1])
			}
			if gotStdin != stdin {
				t.Errorf("original hook stdin = %q, want %q", gotStdin, stdin)
			}
			if gotArg != "origin" {
				t.Errorf("original hook $1 = %q, want %q", gotArg, "origin")
			}
		})
	}
}

func TestMergedPrePushAbortsOnFinding(t *testing.T) {
	stdin := "refs/heads/feature " + testLocalSHA1 + " refs/heads/feature " + testRemoteSHA + "\n" +
		"refs/heads/topic " + testLocalSHA2 + " refs/heads/topic " + testRemoteSHA + "\n"
	calls, gotStdin, _, err := runMergedPrePush(t, "#!/bin/sh", stdin, testLocalSHA2)
	if err == nil {
		t.Fatal("hook succeeded, want failure")
	}
	if exitErr, ok := err.(*exec.ExitError); !ok || exitErr.ExitCode() != 1 {
		t.Errorf("hook error = %v, want exit status 1", err)
	}
	if len(calls) != 2 {
		t.Errorf("gh calls = %q, want 2", calls)
	}
	if gotStdin != "<not run>" {
		t.Error("original hook body ran after a failed scan")
	}
}

func TestMergedPrePushEmptyAndDeletionOnlyInput(t *testing.T) {
	deletion := "(delete) " + testZeroSHA + " refs/heads/old " + testRemoteSHA + "\n"
	for label, stdin := range map[string]string{"empty": "", "deletion": deletion} {
		t.Run(label, func(t *testing.T) {
			calls, gotStdin, _, err := runMergedPrePush(t, "#!/bin/sh", stdin, "")
			if err != nil {
				t.Fatalf("hook failed: %v", err)
			}
			if len(calls) != 0 {
				t.Errorf("gh calls = %q, want none", calls)
			}
			if gotStdin != stdin {
				t.Errorf("original hook stdin = %q, want %q", gotStdin, stdin)
			}
		})
	}
}
